<script setup lang="ts">
import{ref,onMounted}from'vue';import{request}from'../api/client'
interface Settings{movieTemplate:string;seriesTemplate:string;searchCacheSeconds:number;tmdbCacheSeconds:number;embyUserId:string}
const record=ref<{value:Settings;revision:number}|null>(null),busy=ref(false),error=ref(''),message=ref('')
async function load(){try{record.value=await request('/settings/application')}catch(e){error.value=e instanceof Error?e.message:'设置读取失败'}}
async function save(){if(!record.value)return;busy.value=true;error.value='';message.value='';try{record.value=await request('/settings/application',{method:'PUT',body:JSON.stringify(record.value)});message.value='模板与缓存有效期已保存，新的整理预览默认使用模板。不会自动重命名现有文件。'}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="panel section-gap"><div class="panel-title"><h2>媒体命名与搜索缓存</h2><span class="muted">全局默认 · 不自动改动现有媒体</span></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="message" :title="message" type="success" :closable="false"/><form v-if="record" class="connection-form" @submit.prevent="save"><label for="movie-naming-template">电影命名模板</label><el-input id="movie-naming-template" v-model="record.value.movieTemplate"/><label for="series-naming-template">剧集命名模板</label><el-input id="series-naming-template" v-model="record.value.seriesTemplate"/><p class="field-hint">支持 {title}、{year}、{season}、{episode}、{resolution}、{source}、{codec}、{group}、{ext}、{original}。缺失年份不猜造，未知类型需确认；保留扩展名请包含 {ext}。</p><label for="pt-cache-seconds">站点搜索缓存有效期（秒）</label><el-input-number id="pt-cache-seconds" v-model="record.value.searchCacheSeconds" :min="0" :max="86400"/><label for="tmdb-cache-seconds">TMDB 搜索缓存有效期（秒）</label><el-input-number id="tmdb-cache-seconds" v-model="record.value.tmdbCacheSeconds" :min="0" :max="2592000"/><p class="field-hint">0 禁用缓存。站点最多1天，TMDB最多30天。历史保存在PostgreSQL，修改缓存时间不会删除历史。配置变更使旧缓存不再复用。</p><el-button type="primary" native-type="submit" :loading="busy">保存模板与缓存</el-button></form></section></template>
<style scoped>.connection-form{max-width:780px}.field-hint{line-height:1.8}</style>
